function theme(){let p=data().preferences,mode=activeThemeMode(),accent=themeAccent(mode),tokens=themeTokens(mode,accent);document.body.dataset.theme=mode;if(p.contrast){tokens.muted=tokens.text;tokens.line=tokens.text}for(let [key,value] of Object.entries(tokens))document.body.style.setProperty('--'+key,value);document.documentElement.style.setProperty('--scale',p.scale||1);document.body.classList.toggle('high-contrast',!!p.contrast);let nativeKey=mode+':'+accent.id;if(window.Native&&lastNativeTheme!==nativeKey){lastNativeTheme=nativeKey;Native.theme(mode==='dark')}let panel=$('.accent-settings');if(panel)panel.outerHTML=accentSettings()}

function empty(title,body,action,label,symbol='check'){return `<div class="empty"><div class="emblem">${icon(symbol)}</div><h3>${title}</h3><p>${body}</p>${action?`<button class="secondary" data-action="${action}">${label}</button>`:''}</div>`}
function head(title,subtitle='',extra=''){return `<header class="header"><h1>${title}</h1>${extra||`<button class="icon-btn" data-action="search" aria-label="Search everything">${icon('search')}</button>`}</header>`}
function tabbar(){return `<div class="bottom-blur" aria-hidden="true"></div><div class="nav-wrap"><nav class="tabbar" aria-label="Main navigation"><span class="tab-indicator" aria-hidden="true"></span>${['home','boards','calendar','notes'].map(t=>`<button class="tab ${state.tab===t?'active':''}" data-action="tab" data-id="${t}" aria-label="${t==='home'?'Today':t[0].toUpperCase()+t.slice(1)}" ${state.tab===t?'aria-current="page"':''}>${icon(t==='notes'?'note':t)}<span>${t==='home'?'Today':t[0].toUpperCase()+t.slice(1)}</span></button>`).join('')}</nav><button class="fab" data-action="quick" aria-label="Add task, habit, note or reminder">${icon('plus')}</button></div>`}
function boardName(id){return data().boards.find(b=>b.id===id)?.name||'Personal task'}
function taskProgress(t){let sub=M.allSub(t.subtasks||[]);return `${M.isOverdue(t)?`<span class="overdue-tag" title="Originally due ${esc(t.overdueSince)}">Overdue</span>`:''}${sub.length?`<span class="subtask-progress" aria-label="${sub.filter(x=>x.done).length} of ${sub.length} subtasks complete">${icon('check')} ${sub.filter(x=>x.done).length}/${sub.length}</span>`:''}`;}
function taskRow(t){let b=data().boards.find(b=>b.id===t.board);return `<div class="task-row ${t.status==='done'?'done':''} ${expandedTasks.has(t.id)?'is-expanded':''}" data-task="${t.id}" draggable="true"><div class="task-summary"><button class="check ${t.status==='done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${esc(t.title)}"></button><button class="task-main" data-action="task-expand" data-id="${t.id}" aria-expanded="${expandedTasks.has(t.id)}"><div class="task-title">${esc(t.title)}</div>${b||t.priority!=='none'||(t.subtasks||[]).length||M.isOverdue(t)?`<div class="task-meta">${b?`<span class="dot" style="background:${safeColor(b.color)}"></span>${esc(b.name)}`:''}${t.priority!=='none'?`<span class="priority ${t.priority}">${t.priority}</span>`:''}${taskProgress(t)}</div>`:''}</button>${t.dueTime?`<span class="task-time">${timeFormat(t.dueTime)}</span>`:''}${taskEditButton(t)}</div>${taskExpansion(t)}</div>`}

function safeColor(s){return /^#[0-9a-f]{6}$/i.test(s||'')?s:'#72846b'}
function timeFormat(t){let [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
const tasks=()=>data().tasks.filter(t=>!t.archived);
function home(){let day=M.day(),h=new Date().getHours(),g=h<12?'morning':h<17?'afternoon':'evening',today=prioritySorted(tasks().filter(t=>t.dueDate===day),'home'),remaining=today.filter(t=>t.status!=='done').length,overdue=prioritySorted(tasks().filter(t=>t.status!=='done'&&t.dueDate&&t.dueDate<day),'home'),habits=data().habits.filter(h=>M.dueHabit(h)),done=habits.filter(h=>M.habitDone(h)).length,start=M.addDays(day,-((M.date(day).getDay()+6)%7));return `<div class="greeting"><span>Good ${g}, <b>${esc(data().preferences.name)}</b></span><div class="home-actions"><button class="home-avatar" data-action="profile" aria-label="Edit profile">${avatar(data().preferences)}</button><button class="settings-shortcut icon-btn" data-action="open-settings" aria-label="Settings">${icon('settings')}</button></div></div><header class="header home-header"><div><h1>Today<span class="title-dot">.</span></h1><p class="date">${new Date().toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'})}</p></div><button class="icon-btn" data-action="search" aria-label="Search everything">${icon('search')}</button></header><nav class="week-strip" aria-label="This week">${Array.from({length:7},(_,i)=>{let d=M.addDays(start,i),date=M.date(d);return `<button class="week-date ${d===day?'selected':''}" data-action="home-date" data-id="${d}" aria-label="${date.toLocaleDateString(undefined,{dateStyle:'full'})}" ${d===day?'aria-current="date"':''}><span>${date.toLocaleDateString(undefined,{weekday:'short'}).slice(0,1)}</span><strong>${date.getDate()}</strong><i class="${tasks().some(t=>t.dueDate===d&&t.status!=='done')?'has-tasks':''}"></i></button>`}).join('')}</nav><div class="home-layout"><section><div class="section-head"><h2>Your day</h2><div class="section-actions"><small>${remaining?remaining+' left':today.length?'All done':'Take it at your pace'}</small>${prioritySortButton('home')}</div></div><div class="today-tasks">${today.length?today.map(taskRow).join(''):empty("You're all caught up.",'Add something that matters today.','','','sun')}</div><button class="home-add" data-action="add-today">${icon('plus')} Add a task for today</button>${overdue.length?`<details class="overdue"><summary>Overdue <span class="count-pill">${overdue.length}</span></summary><div class="today-tasks">${overdue.map(taskRow).join('')}</div></details>`:''}</section><aside><div class="section-head"><h2>A little momentum</h2></div><div class="two-cards"><button class="mini-card focus-card" data-action="focus"><span class="mini-label">${icon('focus')} Focus</span><div class="mini-value" id="home-timer">${timerText()}</div><small>${data().timer?.running?'In progress':'Start a session'} <span>↗</span></small></button><button class="mini-card" data-action="habits"><span class="mini-label">${icon('habit')} Habits</span><div class="mini-value">${done}<span class="muted"> / ${habits.length}</span></div><small>${habits.length?'Completed today':'Build a routine'} <span>↗</span></small></button></div><button class="notes-shortcut card" data-action="notes">${icon('note')}<span>Notes <small>${data().notes.filter(n=>!n.deletedAt).length?data().notes.filter(n=>!n.deletedAt).length+' saved':'Keep a thought'}</small></span><span class="muted">↗</span></button></aside></div>`}
function boards(){return head('Boards','A place for every part of life.')+`<div class="section-head"><span class="eyebrow">Collections</span><button data-action="new-board">New board +</button></div><div class="board-stack">${data().boards.filter(b=>!b.archived).map(b=>{let ts=tasks().filter(t=>t.board===b.id),done=ts.filter(t=>t.status==='done').length,p=ts.length?Math.round(100*done/ts.length):0;return `<button class="board-tile card" data-board="${b.id}" draggable="true" data-action="board" data-id="${b.id}" style="--board-color:${safeColor(b.color)}"><span class="board-icon">${esc(b.icon||'◈')}</span><div class="board-tile-copy"><h2>${esc(b.name)}</h2><small>${ts.length-done} active · ${(b.lists||[]).length} lists</small></div><div class="board-percent" aria-label="${p}% complete"><strong>${p}%</strong><span>complete</span><div class="progress"><i style="width:${p}%"></i></div></div></button>`}).join('')}</div>${!data().boards.some(b=>!b.archived)?`<div class="card">${empty('Create your first board.','Give a project or part of your life a home.','new-board','Create board','boards')}</div>`:''}`}
function listOptions(board){return [['','No list'],...(data().boards.find(b=>b.id===board)?.lists||[]).map(l=>[l.id,l.name])]}
function boardCard(t){return `<article class="task-card ${t.status==='done'?'done':''} ${expandedTasks.has(t.id)?'is-expanded':''}" data-task="${t.id}" draggable="true"><div class="task-summary"><button class="check ${t.status==='done'?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${esc(t.title)}"></button><button class="task-main" data-action="task-expand" data-id="${t.id}" aria-expanded="${expandedTasks.has(t.id)}"><span class="task-title">${esc(t.title)}</span>${t.priority!=='none'||t.duration||t.dueDate||(t.subtasks||[]).length||M.isOverdue(t)?`<span class="task-meta">${t.priority!=='none'?`<span class="priority ${t.priority}">${t.priority}</span>`:''}${t.duration?`<span>${t.duration} min</span>`:''}${t.dueDate?`<span>${M.date(t.dueDate).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>`:''}${taskProgress(t)}</span>`:''}</button>${taskEditButton(t)}</div>${taskExpansion(t)}</article>`}

function boardScreen(){let b=data().boards.find(x=>x.id===state.board);if(!b){state.board=null;return boards()}let ts=tasks().filter(t=>t.board===b.id),lists=b.lists||[],unlisted=ts.filter(t=>!lists.some(l=>l.id===t.listId));let visible=[...(unlisted.length?[{id:'',name:'Unsorted'}]:[]),...lists];return `<button class="text-btn flex" data-action="back-boards">${icon('arrow')} Boards</button>`+head(esc(b.name),'Your lists. Your own way.',`<div class="board-header-actions"><button class="board-zoom-button" data-action="board-zoom" aria-label="${state.boardZoom?'Zoom in':'Zoom out'}" aria-pressed="${state.boardZoom}">${icon(state.boardZoom?'zoomin':'zoomout')}<span>${state.boardZoom?'Zoom in':'Zoom out'}</span></button><button class="icon-btn" data-action="board-menu" data-id="${b.id}" aria-label="Board options">${icon('more')}</button></div>`)+`<div class="segmented">${['kanban','list'].map(v=>`<button class="${state.boardView===v?'active':''}" data-action="board-view" data-id="${v}">${v==='kanban'?'Board':'List'}</button>`).join('')}</div><div class="board-stage">${boardOverview(visible,ts)}<div class="${state.boardView==='kanban'?'kanban':'board-lists'}" ${state.boardZoom?'hidden':''}>${visible.map(l=>{let items=l.id?ts.filter(t=>t.listId===l.id):unlisted;return `<section class="column" data-list="${l.id}"><div class="list-heading"><h3 tabindex="0" role="button" aria-label="Reorder ${esc(l.name)}" data-list-handle="${l.id}">${esc(l.name)} <small>${items.filter(t=>t.status!=='done').length}</small></h3>${l.id?`<button class="list-options icon-btn" data-action="list-menu" data-id="${l.id}" aria-label="Options for ${esc(l.name)}">${icon('more')}</button>`:''}</div>${items.map(state.boardView==='list'?taskRow:boardCard).join('')}<div class="inline-add"><button class="add-task-pill" data-action="list-add-open" data-id="${l.id}" aria-expanded="false">${icon('plus')} Add task</button><form class="list-task-form" data-list="${l.id}" hidden>${field('title','Task title','','text','required maxlength="240" placeholder="What needs doing?"')}<div class="inline-add-actions"><button class="primary">Add task</button><button type="button" class="icon-btn" data-action="list-add-close" data-id="${l.id}" aria-label="Close add task">×</button></div></form></div></section>`}).join('')}<section class="new-list-card"><form id="list-form">${field('name',lists.length?'Add another list':'Create your first list','','text','required maxlength="60" placeholder="List name"')}<button class="secondary wide">+ Create list</button></form></section></div></div>`}
function calendar(){let d=M.date(state.calDate),first=new Date(d.getFullYear(),d.getMonth(),1),start=M.addDays(M.day(first),-first.getDay());let cells=state.calView==='month'?42:state.calView==='week'?7:1;if(state.calView==='week')start=M.addDays(state.calDate,-d.getDay());if(state.calView==='day')start=state.calDate;let selected=prioritySorted(tasks().filter(t=>t.dueDate===state.calDate).sort((a,b)=>(a.dueTime||'99').localeCompare(b.dueTime||'99')),'calendar');return head('Calendar','A gentler view of your time.')+`<div class="calendar-controls"><button class="text-btn" data-action="cal-today">Today</button><button class="date-pill" data-action="cal-expand" aria-expanded="${state.calView==='month'}">${icon('calendar')} ${state.calView==='month'?'Collapse to week':'Expand month'}</button></div><div class="calendar-layout"><div class="card calendar"><div class="cal-head"><button class="icon-btn" data-action="cal-shift" data-id="-1" aria-label="Previous ${state.calView}">‹</button><h3>${d.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><button class="icon-btn" data-action="cal-shift" data-id="1" aria-label="Next ${state.calView}">›</button></div>${state.calView!=='day'?`<div class="cal-grid">${['S','M','T','W','T','F','S'].map(x=>`<span class="dow">${x}</span>`).join('')}${Array.from({length:cells},(_,i)=>{let s=M.addDays(start,i),dd=M.date(s);return `<button class="cal-day ${s===state.calDate?'selected':''} ${s===M.day()?'today':''} ${dd.getMonth()!==d.getMonth()?'other':''}" data-date="${s}" data-action="cal-date" data-id="${s}" aria-label="${dd.toLocaleDateString(undefined,{dateStyle:'full'})}">${dd.getDate()}${tasks().some(t=>t.dueDate===s)?'<i class="dot"></i>':''}</button>`}).join('')}</div>`:`<div class="empty"><h1 class="serif">${d.getDate()}</h1><p>${d.toLocaleDateString(undefined,{weekday:'long'})}</p></div>`}<button class="text-btn wide" data-action="cal-today">Today</button></div><section><div class="section-head"><h3>${d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</h3><div class="section-actions">${prioritySortButton('calendar')}<button data-action="cal-add">Add +</button></div></div><div class="card">${selected.length?selected.map(taskRow).join(''):empty('A little open space.','Nothing planned for this day.','cal-add','Add a task','calendar')}</div>${state.calView==='day'?`<div class="gap">${Array.from({length:18},(_,i)=>{let hour=String(i+6).padStart(2,'0')+':00';return `<div class="timeline" data-slot="${hour}" data-date="${state.calDate}"><span class="timeline-label">${timeFormat(hour)}</span><button class="result muted" data-action="cal-add-time" data-id="${hour}">${selected.filter(t=>t.dueTime?.startsWith(hour.slice(0,2))).map(t=>esc(t.title)).join(', ')||'—'}</button></div>`}).join('')}</div>`:''}</section></div>`}
function analytics(){let now=M.day(),start=state.period==='week'?M.addDays(now,-M.date(now).getDay()):state.period==='month'?now.slice(0,7)+'-01':'0000-00-00';let completed=data().tasks.filter(t=>t.completedAt&&M.day(new Date(t.completedAt))>=start),scoped=data().tasks.filter(t=>(t.dueDate||t.createdAt.slice(0,10))>=start&&(t.dueDate||t.createdAt.slice(0,10))<=now),mins=data().focusSessions.filter(s=>M.day(new Date(s.createdAt))>=start).reduce((a,s)=>a+s.minutes,0),rate=scoped.length?Math.round(scoped.filter(t=>t.status==='done').length/scoped.length*100):0,streak=0;for(let d=now;;d=M.addDays(d,-1)){if(data().tasks.some(t=>t.completedAt&&M.day(new Date(t.completedAt))===d))streak++;else if(d===now)continue;else break}let counts=Array.from({length:7},(_,i)=>{let d=M.addDays(now,i-6);return {d,n:data().tasks.filter(t=>t.completedAt&&M.day(new Date(t.completedAt))===d).length}}),max=Math.max(1,...counts.map(x=>x.n));return head('Progress','Progress, at your own pace.')+`<div class="segmented">${[['week','This week'],['month','This month'],['all','All time']].map(([v,l])=>`<button class="${state.period===v?'active':''}" data-action="period" data-id="${v}">${l}</button>`).join('')}</div><div class="stat-grid">${[[completed.length,'Tasks completed'],[Math.round(mins/60*10)/10+'h','Focus time'],[streak,'Day streak'],[rate+'%','Completion']].map(([v,l])=>`<div class="stat card"><strong>${v}</strong><small>${l}</small></div>`).join('')}</div><div class="section-head"><span class="eyebrow">Last seven days</span></div><div class="card" style="padding:20px"><div class="bar-chart" role="img" aria-label="${counts.map(x=>x.d+': '+x.n+' completed').join(', ')}">${counts.map(x=>`<div class="bar-item"><small>${x.n}</small><div class="bar" style="height:${x.n/max*80}px"></div><small>${M.date(x.d).toLocaleDateString(undefined,{weekday:'narrow'})}</small></div>`).join('')}</div></div><div class="section-head"><span class="eyebrow">Completed by board</span></div><div class="card">${completed.length?[...data().boards,{id:'',name:'Personal tasks'}].map(b=>{let n=completed.filter(t=>t.board===b.id).length;return n?`<div class="settings-row"><span>${esc(b.name)}</span><small>${Math.round(n/completed.length*100)}%</small></div>`:''}).join(''):empty('Every small step counts.','Your progress will appear as you go.','','','leaf')}</div><p class="help">Completion compares tasks due or created in the selected period through today. Focus time counts finished focus sessions.</p>`}
function more(){let p=data().preferences;const row=(label,action,detail='')=>`<button class="settings-row" data-action="${action}"><span>${label}</span><span><small>${detail}</small> <span class="arrow">›</span></span></button>`;return head('Settings','Make Still feel like you.')+`<button class="profile card wide" data-action="profile">${avatar(p)}<span style="text-align:left"><h3>${esc(p.name)}</h3><small>Personal · on this device</small></span></button><div class="settings-group card">${row('Appearance','appearance',p.theme)}${row('Notifications','notifications',p.notifications?'On':'Off')}${row('Default task settings','defaults')}${row('Focus timer','focus-settings')}</div><div class="settings-group card">${row('Analytics','open-analytics')}${row('All tasks','all-tasks')}${row('Habits','habits')}${row('Notes','notes')}${row('Archived boards & tasks','archive')}</div><div class="settings-group card">${row('Export backup','export')}${row('Import / restore','import')}${row('Shortcuts & widgets','widgets')}${row('App updates','app-updates')}${row('About Still','about')}</div><p class="privacy">${icon('lock')} Your data stays on this device.</p>`}
let profilePhoto='';
function avatar(p){let valid=/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.photo||'');return `<span class="avatar">${valid?`<img src="${p.photo}" alt="Profile photo">`:esc((p.name||'').slice(0,1))}</span>`}
function profileEditor(){profilePhoto=data().preferences.photo||'';sheet('Profile',`<form id="profile-form"><div class="photo-editor"><div id="photo-preview">${avatar(data().preferences)}</div><button type="button" class="secondary" data-action="photo-pick">Choose photo</button><button type="button" class="text-btn" data-action="photo-remove">Remove</button></div><input type="file" id="profile-photo-input" accept="image/*" class="sr-only">${field('name','Your name',data().preferences.name,'text','required maxlength="50"')}<button class="primary wide">Save profile</button></form>`)}
async function readProfilePhoto(file){if(!file||!file.type.startsWith('image/'))throw new Error('Choose an image file.');if(file.size>20*1024*1024)throw new Error('Choose a photo under 20 MB.');let url=URL.createObjectURL(file);try{let img=new Image();await new Promise((r,j)=>{img.onload=r;img.onerror=()=>j(new Error('This image format could not be opened.'));img.src=url});let canvas=document.createElement('canvas');canvas.width=canvas.height=384;let ctx=canvas.getContext('2d'),size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,384,384);return canvas.toDataURL('image/jpeg',.86)}finally{URL.revokeObjectURL(url)}}
document.addEventListener('change',async e=>{if(e.target.id==='habit-remind'){$('#habit-reminder-time').hidden=!e.target.checked;if(!e.target.checked)$('#habit-form [name=reminder]').value='';}if(e.target.id!=='profile-photo-input')return;try{if(!e.target.files[0])return;let photo=await readProfilePhoto(e.target.files[0]);if($('#photo-preview')){profilePhoto=photo;$('#photo-preview').innerHTML=avatar({photo})}}catch(err){toast(err.message)}});
function onboarding(){return `<section class="onboarding"><div class="brand"><span class="brand-mark">${icon('leaf')}</span> Still</div><h1 class="serif">A little space.<br>A clearer day.</h1><p>Your tasks, routines, and moments of focus. All in one quiet place.</p><form id="welcome-form"><label class="eyebrow" for="welcome-name">What should we call you?</label><input id="welcome-name" name="name" placeholder="Your name" autocomplete="given-name" required maxlength="50"><button class="primary wide" type="submit">Make yourself at home &nbsp; →</button></form><p class="privacy">${icon('lock')} Just your name. Everything stays on your device.</p></section>`}
let lastRenderedDay='',lastNativeTheme=null;
function render(){let boardScroll=$('.kanban')?.scrollLeft||0;theme();lastRenderedDay=M.day();if(!data().preferences.name){$('#app').innerHTML=onboarding();return}let content=state.tab==='home'?home():state.tab==='boards'?(state.board?boardScreen():boards()):state.tab==='calendar'?calendar():state.tab==='analytics'?analytics():state.tab==='notes'?notesScreen():more();let screen=$('#app > .screen');if(screen){screen.innerHTML=content;syncTabbar()}else{$('#app').innerHTML=`<div class="screen">${content}</div>${tabbar()}`;syncTabbar()}if($('.kanban'))$('.kanban').scrollLeft=boardScroll;}
function syncTabbar(){let tabs=['home','boards','calendar','notes'],index=tabs.indexOf(state.tab);let bar=$('.tabbar');if(!bar)return;bar.style.setProperty('--nav-offset',Math.max(0,index)*100+'%');bar.style.setProperty('--nav-gap',Math.max(0,index)*2+'px');bar.classList.toggle('no-active-tab',index<0);bar.querySelectorAll('.tab').forEach(b=>{let selected=b.dataset.id===state.tab;b.classList.toggle('active',selected);if(selected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}

function sheet(title,html,onOpen,modal=false,anchor=null){captureSheet();let previous=document.activeElement;sheets.push({title,html,onOpen,previous,scroll:0,modal,anchor});drawSheet()}
function drawSheet(){let e=sheets.at(-1),overlay=$('#overlay');if(!e){overlay.innerHTML='';$('#app').inert=false;document.body.style.overflow='';return}$('#app').inert=true;document.body.style.overflow='hidden';let section=$('.sheet');if(!section){overlay.innerHTML='<div class="backdrop"><section class="sheet"></section></div>';section=$('.sheet')}section.className='sheet'+(e.modal?'':' page')+(e.anchor?' list-popover':'');section.removeAttribute('style');section.parentElement.className='backdrop'+(e.modal?'':' page-backdrop')+(e.anchor?' popover-backdrop':'');section.setAttribute('role',e.modal?'dialog':'region');section.setAttribute('aria-label',e.title);e.modal?section.setAttribute('aria-modal','true'):section.removeAttribute('aria-modal');section.innerHTML=`<div class="handle"></div><div class="sheet-head"><button data-action="close" aria-label="${e.modal?'Close':'Go back'}">${e.modal?'×':icon('arrow')}</button><h2>${esc(e.title)}</h2></div><div class="sheet-content">${e.html}</div>`;let form=section.querySelector('.sheet-content > form[id]');if(!e.modal&&form){section.querySelector('.sheet-head').insertAdjacentHTML('beforeend',`<button class="header-save" type="submit" form="${form.id}">Save</button>`);form.querySelectorAll('button.primary:not([type=button]),.note-actions button[type=submit]').forEach(b=>{b.hidden=true});}let content=section.querySelector('.sheet-content');content.scrollTop=e.scroll||0;section.classList.toggle('scrolled',content.scrollTop>8);if(e.anchor)positionListPopover(section,e.anchor);$('.sheet-head button')?.focus({preventScroll:true});if(e.onOpen)e.onOpen();updateViewport()}
function closeSheet(){if($('#note-form'))flushNote();let e=sheets.pop();drawSheet();if(!sheets.length){render();e?.previous?.focus?.({preventScroll:true})}}
function closeAll(){if($('#note-form'))flushNote();sheets=[];drawSheet()}
function replaceSheet(title,html,onOpen){sheets.pop();sheets.push({title,html,onOpen,scroll:0});drawSheet()}
function picker(name,label,value,options){let match=options.find(x=>x[0]===String(value));return `<div class="field inline-picker"><span>${label}</span><input type="hidden" name="${name}" value="${esc(value)}"><button type="button" class="picker" data-picker="${name}" data-label="${esc(label)}" aria-expanded="false" data-options="${esc(JSON.stringify(options))}">${esc(match?.[1]||value||'None')}</button><div class="inline-choices" hidden>${options.map(([v,l])=>`<button type="button" class="choice ${String(value)===v?'active':''}" data-pick-value="${esc(v)}" data-pick-name="${name}">${esc(l)}</button>`).join('')}</div></div>`}
function priorityBar(name,value){return `<fieldset class="priority-field"><legend>Priority</legend><input type="hidden" name="${name}" value="${esc(value)}"><div class="segmented priority-bar" role="group" aria-label="Priority">${['none','low','medium','high'].map(p=>`<button type="button" class="${p===value?'active':''}" data-priority="${p}" aria-pressed="${p===value}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div></fieldset>`}
function field(name,label,value='',type='text',extra=''){if(type==='color')return colorField(name,label,value);return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function captureSheet(){let e=sheets.at(-1);if(!e)return;let s=$('.sheet');if(!s)return;e.scroll=s.querySelector('.sheet-content').scrollTop;s.querySelectorAll('input').forEach(x=>{if(x.type!=='file'){x.setAttribute('value',x.value);if(x.type==='checkbox'){x.toggleAttribute('checked',x.checked)}}});s.querySelectorAll('textarea').forEach(x=>x.textContent=x.value);e.html=s.querySelector('.sheet-content').innerHTML}
function quick(){sheet('Create',`<div class="quick-menu">${[['new-task','check','Task'],['new-habit','habit','Habit'],['new-note','note','Note'],['new-reminder','bell','Reminder']].map(([a,i,t])=>`<button data-action="${a}"><span>${icon(i)}</span>${t}</button>`).join('')}</div>`,null,true);$('.sheet').classList.add('quick-sheet')}
function taskEditor(id,opts={}){if(sheets.length)captureSheet();sheets=[];draft=id?structuredClone(data().tasks.find(t=>t.id===id)):M.entity({title:'',description:'',board:state.board||'',status:'todo',priority:data().preferences.defaultPriority||'none',dueDate:M.day(),listId:'',dueTime:'',startTime:'',duration:'',reminder:false,repeat:'none',repeatDays:[],interval:1,repeatEnd:'',repeatBehavior:'scheduled',tags:[],subtasks:[],notes:'',attachments:[],...opts});if(draft.notes){draft.description=[draft.description,draft.notes].filter(Boolean).join('\n\n');draft.notes=''}if(!id&&draft.board&&!('listId' in opts))draft.listId=(data().boards.find(b=>b.id===draft.board)?.lists||[])[0]?.id||'';taskSheet()}
function taskSheet(){let t=draft,sub=M.allSub(t.subtasks),exists=data().tasks.some(x=>x.id===t.id);sheet(exists?'Task':t.kind==='reminder'?'New reminder':'New task',`<form id="task-form" class="app-editor">
<label class="task-title-field"><span>Task name</span><input class="title-input plain-title" name="title" aria-label="Task title" placeholder="What needs doing?" required maxlength="240" value="${esc(t.title)}"></label>
<details class="schedule-options" ${t.kind==='reminder'?'open':''}><summary><span class="schedule-label">${t.dueDate?(t.dueDate===M.day()?'Today':M.date(t.dueDate).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})):'No date'}</span><span class="date-icon" aria-label="Choose another date">${icon('calendar')}</span></summary><div class="form-grid">${field('dueDate','Day',t.dueDate,'date')}${field('dueTime','Time · optional',t.dueTime,'time')}</div><label class="switch-row"><span>Remind me<small>At the selected date and time</small></span><input type="checkbox" role="switch" name="reminder" ${t.reminder?'checked':''}></label><button type="button" class="text-btn" data-action="clear-due">No date or time</button></details>
<label class="field task-details-field"><span>Details <small>Optional</small></span><textarea class="plain-description" rows="1" name="description" placeholder="Add details…">${esc(t.description)}</textarea></label>
${t.attachments.length?`<div class="existing-task-files" id="attachments">${attachmentList(t.attachments)}</div>`:''}
${priorityBar('priority',t.priority)}
<details class="editor-group"><summary>Organize <small>${esc(t.board?boardName(t.board)+(listOptions(t.board).find(l=>l[0]===t.listId)?.[1]?' · '+listOptions(t.board).find(l=>l[0]===t.listId)[1]:''):'Personal task')}</small></summary><div class="form-grid">${picker('board','Board · optional',t.board,[['','Personal task'],...data().boards.filter(b=>!b.archived).map(b=>[b.id,b.name])])}<div id="task-list-picker">${picker('listId','List · optional',t.listId||'',listOptions(t.board))}</div></div>${field('tags','Tags · comma separated',t.tags.join(', '))}</details>
<details class="editor-group" id="task-checklist"><summary>Subtasks <small id="subtask-count">${sub.length?sub.filter(x=>x.done).length+' / '+sub.length:'None'}</small></summary><div id="subtasks">${subtree(t.subtasks)}</div><button type="button" class="add-task-pill" data-action="sub-add" data-id="">Add subtask</button></details>
<details class="editor-group" id="task-repeat"><summary>Repeat <small id="repeat-summary">${esc(repeatLabel(t.repeat,t.interval))}</small></summary><input type="hidden" name="status" value="${t.status}">
${picker('repeat','How often?',t.repeat,[['none','Does not repeat'],['daily','Every day'],['weekly','Every week'],['monthly','Every month'],['weekdays','Choose weekdays'],['custom','Every few days']])}
<div id="repeat-interval">${field('interval','Repeat every … days',t.interval,'number','min="1" max="365"')}</div>
<div id="repeat-weekdays"><span class="field-label">On these days</span><div class="weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<button type="button" class="${t.repeatDays.includes(i)?'active':''}" data-action="repeat-day" data-id="${i}" aria-pressed="${t.repeatDays.includes(i)}">${d}</button>`).join('')}</div></div>
<div id="repeat-options">${field('repeatEnd','End date · optional',t.repeatEnd,'date')}<div id="repeat-base">${picker('repeatBehavior','Calculate the next date from',t.repeatBehavior,[['scheduled',"This task’s due date"],['completion','The day I complete it']])}</div><p class="help repeat-help">Completing this task creates the next one.</p></div></details>
<div class="estimate-row"><label for="task-estimate">Time estimate <small>Optional</small></label><div><input id="task-estimate" name="duration" type="number" min="1" max="10080" inputmode="numeric" placeholder="—" value="${esc(t.duration)}"><span>min</span></div></div>
${t.startTime?field('startTime','Planned start',t.startTime,'time'):`<input type="hidden" name="startTime" value="">`}
${exists?`<div class="task-editor-actions"><button type="button" class="secondary" data-action="save-complete">${t.status==='done'?'Reopen':'Complete'}</button><button type="button" class="secondary" data-action="focus-task">${icon('focus')} Focus</button><button type="button" class="icon-btn danger" data-action="delete-task" data-id="${t.id}" aria-label="Delete task">${icon('trash')}</button></div>`:''}</form>`,()=>{syncRepeatOptions();resizeTaskDetails()})}
function repeatLabel(repeat,interval=1){let n=Math.max(1,Number(interval)||1);return repeat==='none'?'Does not repeat':repeat==='weekdays'?'Selected weekdays':repeat==='custom'?`Every ${n} days`:n>1?`Every ${n} ${repeat==='weekly'?'weeks':repeat==='monthly'?'months':'days'}`:({daily:'Every day',weekly:'Every week',monthly:'Every month'}[repeat]||'Does not repeat')}
function syncRepeatOptions(){let f=$('#task-form');if(!f)return;let r=f.elements.repeat.value,n=Number(f.elements.interval.value)||1;$('#repeat-interval').hidden=!(r==='custom'||(['daily','weekly','monthly'].includes(r)&&n>1));$('#repeat-interval .field>span').textContent='Repeat every … '+(r==='weekly'?'weeks':r==='monthly'?'months':'days');$('#repeat-weekdays').hidden=r!=='weekdays';$('#repeat-options').hidden=r==='none';$('#repeat-base').hidden=r==='weekdays';$('#repeat-summary').textContent=repeatLabel(r,n)}
function resizeTaskDetails(){let e=$('#task-form [name=description]');if(!e)return;e.style.height='auto';e.style.height=Math.max(44,Math.min(150,e.scrollHeight))+'px'}
function refreshSubtasks(){let e=$('#subtasks');if(!e)return;e.innerHTML=subtree(draft.subtasks);let sub=M.allSub(draft.subtasks),count=$('#subtask-count');if(count)count.textContent=sub.length?sub.filter(x=>x.done).length+' / '+sub.length:'None'}

function subtree(arr,depth=0){return arr.map(s=>`<div class="subtask" style="--depth:${Math.min(depth,8)}"><button type="button" class="check ${s.done?'checked':''}" data-action="sub-toggle" data-id="${s.id}" aria-label="Toggle ${esc(s.title)}"></button><button type="button" class="sub-title" data-action="sub-edit" data-id="${s.id}">${esc(s.title)}</button><button type="button" class="icon-btn danger" data-action="sub-delete" data-id="${s.id}" aria-label="Delete subtask">×</button></div>${subtree(s.children||[],depth+1)}`).join('')}
function attachmentList(arr){return arr.map(a=>`<div class="file-item"><button type="button" class="text-btn" data-action="open-attachment" data-id="${a.id}">${esc(a.name)}</button><small>${Math.round(a.size/1024)} KB</small><button type="button" class="danger" data-action="remove-attachment" data-id="${a.id}" aria-label="Remove attachment">×</button></div>`).join('')}
function readTaskForm(){let f=$('#task-form');if(!f)return;let v=new FormData(f);for(let k of ['title','board','listId','priority','dueDate','dueTime','status','description','startTime','duration','repeat','repeatEnd','repeatBehavior','notes'])if(v.has(k))draft[k]=String(v.get(k)||'');draft.title=draft.title.trim();draft.interval=Math.max(1,Number(v.get('interval'))||1);draft.tags=String(v.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean);draft.reminder=v.has('reminder');if(!draft.dueDate){draft.dueTime='';draft.reminder=false}if(!listOptions(draft.board).some(l=>l[0]===draft.listId))draft.listId=''}
async function saveTask(complete=false){readTaskForm();if(!draft.title){toast('Give your task a title.');return false}if(draft.repeat==='weekdays'&&!draft.repeatDays.length){toast('Choose at least one repeat day.');return false}if(draft.reminder&&(!draft.dueDate||!draft.dueTime)){toast('Add a date and time for the reminder.');return false}let existing=data().tasks.find(t=>t.id===draft.id);let previous=existing?.status;if(existing&&draft.dueDate!==existing.dueDate)draft.overdueSince=null;draft.updatedAt=M.now();let wantDone=draft.status==='done';draft.status=previous||'todo';if(existing)Object.assign(existing,draft);else{existing=structuredClone(draft);data().tasks.push(existing)}if(complete)M.toggleTask(existing.id);else if(wantDone!==(previous==='done'))M.toggleTask(existing.id);else existing.status=draft.status=String(new FormData($('#task-form')).get('status')||'todo');if(await persist()){closeAll();render();toast(complete?'Task updated':'Saved');return true}return false}
function boardEditor(id){let b=data().boards.find(x=>x.id===id)||M.entity({name:'',icon:'◈',color:'#72846b'});sheet(id?'Edit board':'New board',`<form id="board-form" data-id="${b.id}">${field('name','Board name',b.name,'text','required maxlength="60"')}<div class="form-grid">${picker('icon','Icon',b.icon,[['◈','◈ Diamond'],['☼','☼ Sun'],['✦','✦ Star'],['♡','♡ Heart'],['◎','◎ Circle'],['⚑','⚑ Flag'],['⌂','⌂ Home']])}${field('color','Color',b.color,'color')}</div><button class="primary wide">Save board</button>${id?`<button type="button" class="delete-bottom" data-action="delete-board" data-id="${id}">Delete board</button>`:''}</form>`)}
function habitEditor(id){let h=data().habits.find(x=>x.id===id)||M.entity({name:'',icon:'✦',color:'#72846b',frequency:'daily',interval:1,days:[],target:1,reminder:'',startDate:M.day(),completions:[],paused:false});sheet(id?'Edit habit':'New habit',`<form id="habit-form" class="app-editor" data-id="${h.id}"><input class="plain-title" name="name" placeholder="A habit to build" aria-label="Habit name" value="${esc(h.name)}" required maxlength="100"><div class="field"><span>How often?</span><input type="hidden" name="frequency" value="${h.frequency}"><div class="habit-frequency">${[['daily','Every day'],['weekdays','Choose days'],['weekly','Weekly'],['custom','Every few days']].map(([v,l])=>`<button type="button" data-action="habit-frequency" data-id="${v}" aria-pressed="${v===h.frequency}" class="${v===h.frequency?'active':''}">${l}</button>`).join('')}</div></div><div data-habit-panel="weekdays" ${h.frequency==='weekdays'?'':'hidden'}><p class="help">Repeat on these days</p><div class="day-chips">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${h.days.includes(i)?'checked':''}><span>${d}</span></label>`).join('')}</div></div><div data-habit-panel="custom" ${h.frequency==='custom'?'':'hidden'}>${field('interval','Repeat every … days',h.interval||1,'number','min="1" max="365"')}</div><p class="help" data-habit-panel="weekly" ${h.frequency==='weekly'?'':'hidden'}>Repeats on the same weekday as your start date.</p><div class="app-group">${field('target','Daily goal · number of times',h.target,'number','min="1" max="100" required')}${field('startDate','Start on',h.startDate,'date','required')}</div><label class="switch-row"><span>Reminder<small>Get a gentle nudge at a set time</small></span><input type="checkbox" role="switch" id="habit-remind" ${h.reminder?'checked':''}></label><div id="habit-reminder-time" ${h.reminder?'':'hidden'}>${field('reminder','Remind me at',h.reminder,'time')}</div><details class="editor-group"><summary>Personalize <small>Icon & color</small></summary><div class="form-grid">${picker('icon','Icon',h.icon,[['✦','✦ Star'],['♡','♡ Heart'],['◎','◎ Circle'],['☼','☼ Sun'],['◈','◈ Diamond']])}${field('color','Color',h.color,'color')}</div></details>${id?`<label class="switch-row"><span>Pause habit<small>Keep your history and stop scheduled check-ins</small></span><input type="checkbox" role="switch" name="paused" ${h.paused?'checked':''}></label><button class="delete-bottom" type="button" data-action="delete-habit" data-id="${id}">Delete habit</button>`:''}</form>`)}
function habits(){let hs=data().habits;sheet('Habits',`<div class="section-head"><span class="eyebrow">Your habits</span><button data-action="new-habit">Add +</button></div><div class="card">${hs.length?hs.map(h=>`<div class="habit-row"><div class="flex"><button class="habit-info" data-action="habit-detail" data-id="${h.id}"><h3><span style="color:${safeColor(h.color)}">${esc(h.icon)}</span> ${esc(h.name)}</h3><small>${h.paused?'Paused':M.streak(h)+' day streak'} · ${M.habitCount(h)} / ${h.target} today</small></button><button class="check ${M.habitDone(h)?'checked':''}" data-action="habit-complete" data-id="${h.id}" ${!M.dueHabit(h)?'disabled':''} aria-label="Log ${esc(h.name)}"></button></div><div class="habit-dots">${Array.from({length:7},(_,i)=>{let d=M.addDays(M.day(),i-6);return `<div class="habit-day ${!M.habitAvailable(h,d)?'unavailable':''}" title="${!M.habitAvailable(h,d)?'Not available before habit start':d}">${M.date(d).toLocaleDateString(undefined,{weekday:'narrow'})}<i class="${M.habitAvailable(h,d)&&M.habitDone(h,d)?'filled':''}"></i></div>`}).join('')}</div></div>`).join(''):empty('Build a small routine.','A little consistency goes a long way.','new-habit','Add your first habit','leaf')}</div>`)}
function habitDetail(id){let h=data().habits.find(x=>x.id===id);sheet(h.name,`<div class="stat-grid"><div class="stat card"><strong>${M.streak(h)}</strong><small>day streak</small></div><div class="stat card"><strong>${new Set(h.completions.map(c=>c.date)).size}</strong><small>days logged</small></div></div><div class="section-head"><span class="eyebrow">Last 28 days</span></div><div class="cal-grid">${Array.from({length:28},(_,i)=>{let d=M.addDays(M.day(),i-27);return `<div class="cal-day ${!M.habitAvailable(h,d)?'unavailable':M.habitDone(h,d)?'selected':''}" aria-label="${d}: ${!M.habitAvailable(h,d)?'Not available before habit start':M.habitCount(h,d)+' logs'}">${M.date(d).getDate()}</div>`}).join('')}</div><button class="secondary wide gap" data-action="edit-habit" data-id="${id}">Edit routine</button><p class="help">${h.frequency==='daily'?'Daily':h.frequency==='weekly'?'Weekly':h.frequency==='custom'?'Every '+h.interval+' days':h.days.map(i=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][i]).join(', ')} · Target ${h.target} per scheduled day</p>`)}
function search(){sheet('Search',`<input class="search-input" id="search-input" type="search" placeholder="Tasks, notes, boards, habits…" aria-label="Search locally" value="${esc(state.searchQ)}"><div class="segmented">${['all','tasks','notes','boards','habits'].map(t=>`<button data-action="search-filter" data-id="${t}" class="${state.searchType===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="search-results"></div>`,searchResults)}
function searchResults(){if(!$('#search-results'))return;let r=M.search(state.searchQ,state.searchType);$('#search-results').innerHTML=r.length?r.map(({kind,label,item})=>`<button class="result" data-action="${{tasks:'task',boards:'board-search',notes:'edit-note',habits:'habit-detail'}[kind]}" data-id="${item.id}"><div>${esc(item.title||item.name)}</div><small>${label}${kind==='tasks'?' · '+esc(boardName(item.board)):''}</small></button>`).join(''):`<p class="help">${state.searchQ?'Nothing found. Try another word.':'Everything is searched privately on this device.'}</p>`}
function timerRemaining(){let t=data().timer;if(!t)return data().preferences[(typeof focusMode==='string'?focusMode:'focus')+'Minutes']*60;return Math.max(0,t.running?Math.ceil((t.endAt-Date.now())/1000):t.remaining)}
function timerText(){let s=timerRemaining();return s>=3600?`${Math.floor(s/3600)}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`:`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
let focusMode='focus',focusTask='';
function focus(){let t=data().timer;if(t){focusMode=t.mode;focusTask=t.task||''}let modes=[['focus','Focus'],['short','Short break'],['long','Long break']];sheet('Focus',`<div class="segmented">${modes.map(([v,l])=>`<button data-action="focus-mode" data-id="${v}" class="${focusMode===v?'active':''}" ${t?.running?'disabled':''}>${l}</button>`).join('')}</div><div class="timer-wrap"><div class="timer"><svg viewBox="0 0 260 260" aria-hidden="true"><circle cx="130" cy="130" r="120"/><circle class="elapsed" cx="130" cy="130" r="120" stroke-dasharray="754" stroke-dashoffset="0"/></svg><div><button class="timer-number" id="timer-number" data-action="duration-picker" aria-label="Set timer duration">${timerText()}</button><div class="timer-label">${t?.running?(focusMode==='focus'?'Focusing':'On a break'):t?'Paused':'Set duration'}</div></div></div>${recentDurationButtons()}<div class="flex timer-controls"><button class="secondary" data-action="timer-stop">Stop</button><button class="primary" data-action="timer-toggle">${t?.running?'Pause':t?'Resume':focusMode==='focus'?'Start focus':'Start break'}</button></div></div>${picker('focusTask','Current task',focusTask,[['','Just focus'],...tasks().filter(t=>t.status!=='done').map(t=>[t.id,t.title])])}${window.Native?.exactTimersAllowed&&!Native.exactTimersAllowed()?'<button class="text-btn wide" data-action="timer-permission">Enable precise timers</button>':''}${data().focusSessions.length?'<div class="section-head"><span class="eyebrow">Recent focus</span></div>':''}${data().focusSessions.slice(-4).reverse().map(s=>`<div class="settings-row"><span>${esc(data().tasks.find(t=>t.id===s.task)?.title||'Focused time')}</span><small>${s.minutes} min · ${new Date(s.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></div>`).join('')||''}`)}
function focusSettings(){let p=data().preferences;sheet('Focus settings',`<form id="focus-settings-form">${field('focusMinutes','Focus · minutes',p.focusMinutes,'number','min="1" max="1439" required')}${field('shortMinutes','Short break · minutes',p.shortMinutes,'number','min="1" max="1439" required')}${field('longMinutes','Long break · minutes',p.longMinutes,'number','min="1" max="1439" required')}<button class="primary wide">Save durations</button></form>`)}
async function timerTick(){if(data()?.timer?.running&&timerRemaining()===0)window.syncNativeTimer();let t=data()?.timer;if(t?.running&&timerRemaining()===0){if(window.Native?.timerFinished)Native.timerFinished(t.id,t.endAt,t.mode);if(t.mode==='focus')data().focusSessions.push(M.entity({minutes:t.total/60,task:t.task||''}));data().timer=null;await persist();haptic();toast(t.mode==='focus'?'Focus session completed ✓':'Break complete');if(sheets.at(-1)?.title==='Focus'){closeSheet();focus()}render()}if($('#timer-number')){$('#timer-number').textContent=timerText();$('.elapsed').style.strokeDashoffset=String(754*(1-timerRemaining()/(data().timer?.total||data().preferences[focusMode+'Minutes']*60)))}if($('#home-timer'))$('#home-timer').textContent=timerText()}
function confirmation(title,body,action,id){sheet(title,`<p class="help">${body}</p><button class="primary wide gap" data-action="${action}" data-id="${id||''}">Confirm</button><button class="text-btn wide" data-action="close">Cancel</button>`,null,true)}
async function action(a,id,el){switch(a){
case 'close':closeSheet();break;
case 'tab':if(state.tab===id&&!state.board&&!sheets.length)break;state.tab=id;state.board=null;closeAll();render();window.scrollTo(0,0);break;
case 'quick':quick();break;
case 'new-task':taskEditor();break;
case 'home-date':state.tab='calendar';state.calDate=id;state.calView='week';render();window.scrollTo(0,0);break;
case 'add-today':taskEditor(null,{dueDate:M.day()});break;
case 'open-analytics':closeAll();state.tab='analytics';render();break;
case 'new-task-status':taskEditor(null,{status:id});break;
case 'new-reminder':taskEditor(null,{kind:'reminder',reminder:true});break;
case 'task':taskEditor(id);break;
case 'task-expand':toggleTaskExpansion(id);break;
case 'inline-sub-toggle':await toggleInlineSubtask(el.dataset.parentTask,id);break;
case 'sort-priority':await togglePrioritySort(id);break;
case 'open-settings':state.tab='more';state.board=null;closeAll();render();window.scrollTo(0,0);break;
case 'complete':M.toggleTask(id);await persist();haptic();render();if(sheets.at(-1)?.title==='All your tasks'){sheets.pop();action('all-tasks')}break;
case 'save-complete':await saveTask(true);break;
case 'delete-task':confirmation('Delete this task?','The task and its attachments will be removed.','confirm-delete-task',id);break;
case 'confirm-delete-task':data().tasks=data().tasks.filter(t=>t.id!==id);await persist();closeAll();render();break;
case 'task-menu':sheet('Task actions',`<div class="choices"><button class="choice" data-action="task" data-id="${id}">Edit task</button><button class="choice" data-action="menu-complete" data-id="${id}">Toggle completion</button><button class="choice" data-action="archive-task" data-id="${id}">Archive task</button><button class="choice danger" data-action="delete-task" data-id="${id}">Delete task</button></div>`);break;
case 'menu-complete':M.toggleTask(id);await persist();closeAll();render();break;
case 'archive-task':data().tasks.find(t=>t.id===id).archived=true;await persist();closeAll();render();break;
case 'repeat-day':readTaskForm();draft.repeatDays=draft.repeatDays.includes(+id)?draft.repeatDays.filter(x=>x!==+id):[...draft.repeatDays,+id];el.classList.toggle('active');el.setAttribute('aria-pressed',String(draft.repeatDays.includes(+id)));break;
case 'sub-add':case 'sub-edit':readTaskForm();captureSheet();let s=id?M.allSub(draft.subtasks).find(x=>x.id===id):null;sheet(a==='sub-edit'?'Edit subtask':'Add subtask',`<form id="sub-form" data-parent="${id}" data-edit="${a==='sub-edit'}">${field('title','What is the next step?',a==='sub-edit'?s.title:'','text','required maxlength="200" autocomplete="off"')}<button class="primary wide">${a==='sub-edit'?'Save changes':'Add subtask'}</button></form>`,()=>$('#sub-form input').focus({preventScroll:true}),true);break;
case 'sub-toggle':{let s=M.allSub(draft.subtasks).find(x=>x.id===id);s.done=!s.done;s.updatedAt=M.now();refreshSubtasks();break}
case 'sub-delete':{const remove=arr=>arr.filter(x=>x.id!==id).map(x=>({...x,children:remove(x.children||[])}));draft.subtasks=remove(draft.subtasks);refreshSubtasks();break}
case 'attach':$('#file-input').click();break;
case 'remove-attachment':draft.attachments=draft.attachments.filter(x=>x.id!==id);$('#attachments').innerHTML=attachmentList(draft.attachments);break;
case 'open-attachment':{let a=draft.attachments.find(x=>x.id===id);if(window.Native)Native.exportAttachment(a.name,a.data);else download(a.name,a.data);break}
case 'new-board':boardEditor();break;
case 'board':case 'board-search':state.boardZoom=false;closeAll();state.tab='boards';state.board=id;render();break;
case 'list-up':case 'list-down':{let ls=data().boards.find(b=>b.id===state.board).lists,i=ls.findIndex(l=>l.id===id),next=i+(a==='list-up'?-1:1);if(next>=0&&next<ls.length){ls.splice(next,0,ls.splice(i,1)[0]);await persist();render()}break}
case 'list-menu':listMenu(id,el);break;
case 'list-add-open':toggleListAdd(id,true);break;
case 'list-add-close':toggleListAdd(id,false);break;
case 'edit-list':editList(id);break;
case 'duplicate-list':await duplicateList(id);break;
case 'delete-list':confirmation('Delete this list?','This list and all its tasks, including completed and archived tasks, subtasks and attachments, will be permanently deleted.','confirm-delete-list',id);break;
case 'confirm-delete-list':await deleteList(id);break;
case 'back-boards':state.board=null;render();break;
case 'board-view':state.boardZoom=false;state.boardView=id;render();break;
case 'board-zoom':setBoardZoom(!state.boardZoom);break;
case 'board-overview-list':zoomIntoList(id);break;
case 'board-menu':sheet('Board options',`<div class="choices"><button class="choice" data-action="edit-board" data-id="${id}">Edit name, icon & color</button><button class="choice" data-action="archive-done" data-id="${id}">Archive completed tasks</button><button class="choice" data-action="archive-board" data-id="${id}">Archive board</button><button class="choice danger" data-action="delete-board" data-id="${id}">Delete board</button></div>`);break;
case 'edit-board':boardEditor(id);break;
case 'archive-done':data().tasks.filter(t=>t.board===id&&t.status==='done').forEach(t=>t.archived=true);await persist();closeAll();render();break;
case 'archive-board':data().boards.find(b=>b.id===id).archived=true;state.board=null;await persist();closeAll();render();break;
case 'delete-board':confirmation('Delete this board?','Tasks will be kept as personal tasks.','confirm-delete-board',id);break;
case 'confirm-delete-board':data().boards=data().boards.filter(b=>b.id!==id);data().tasks.filter(t=>t.board===id).forEach(t=>{t.board='';t.listId=''});state.board=null;await persist();closeAll();render();break;
case 'habit-frequency':$('#habit-form [name=frequency]').value=id;$$('[data-action=habit-frequency]').forEach(b=>{b.classList.toggle('active',b.dataset.id===id);b.setAttribute('aria-pressed',b.dataset.id===id)});$$('[data-habit-panel]').forEach(p=>p.hidden=p.dataset.habitPanel!==id);break;
case 'cal-expand':state.calView=state.calView==='month'?'week':'month';render();break;
case 'cal-view':state.calView=id;render();break;
case 'cal-date':state.calDate=id;render();break;
case 'cal-today':state.calDate=M.day();render();break;
case 'cal-shift':{let d=M.date(state.calDate);if(state.calView==='month'){d.setDate(1);d.setMonth(d.getMonth()+Number(id))}else d.setDate(d.getDate()+Number(id)*(state.calView==='week'?7:1));state.calDate=M.day(d);render();break}
case 'cal-add':taskEditor(null,{dueDate:state.calDate});break;
case 'cal-add-time':taskEditor(null,{dueDate:state.calDate,dueTime:id});break;
case 'period':state.period=id;render();break;
case 'habits':habits();break;
case 'new-habit':if($('.quick-sheet'))closeAll();habitEditor();break;
case 'edit-habit':habitEditor(id);break;
case 'habit-detail':habitDetail(id);break;
case 'habit-complete':M.toggleHabit(id);await persist();haptic();sheets.pop();habits();render();break;
case 'delete-habit':confirmation('Delete this habit?','Its completion history will also be removed.','confirm-delete-habit',id);break;
case 'confirm-delete-habit':data().habits=data().habits.filter(h=>h.id!==id);await persist();closeAll();habits();render();break;
case 'note-folder':notesFolder=id;render();break;
case 'note-folders':manageNoteFolders();break;
case 'new-note-folder':folderEditor();break;
case 'edit-note-folder':folderEditor(id);break;
case 'delete-note-folder':confirmation('Delete folder?','Its notes will be kept in Unfiled.','confirm-delete-note-folder',id);break;
case 'confirm-delete-note-folder':data().preferences.noteFolders=noteFolders().filter(f=>f.id!==id);data().notes.filter(n=>n.folderId===id).forEach(n=>{n.folderId='';n.updatedAt=M.now()});notesFolder='all';await persist();closeAll();state.tab='notes';render();break;
case 'notes-trash':notesTrash();break;
case 'restore-note':{let n=data().notes.find(n=>n.id===id);if(n){delete n.deletedAt;n.updatedAt=M.now();}await persist();closeSheet();notesTrash();render();break;}
case 'erase-note':confirmation('Delete forever?','This permanently removes the note from this device.','confirm-erase-note',id);break;
case 'confirm-erase-note':data().notes=data().notes.filter(n=>n.id!==id);await persist();closeAll();notesTrash();render();break;
case 'notes':closeAll();state.tab='notes';state.board=null;render();break;
case 'note-export':await exportNote(id);break;
case 'new-note':if($('.quick-sheet'))closeAll();noteEditor();break;
case 'edit-note':noteEditor(id);break;
case 'delete-note':await flushNote();confirmation('Move note to trash?','You can restore it from Notes → Trash.','confirm-delete-note',id);break;
case 'confirm-delete-note':clearTimeout(noteSaveTimer);noteDraft=null;{let n=data().notes.find(n=>n.id===id);if(n){n.deletedAt=M.now();n.updatedAt=M.now();}}await persist();closeAll();render();break;
case 'search':search();break;
case 'search-filter':state.searchType=id;$$('[data-action=search-filter]').forEach(b=>b.classList.toggle('active',b.dataset.id===id));searchResults();break;
case 'focus':focus();break;
case 'focus-task':{let tid=draft.id;if(await saveTask()){focusTask=tid;if(data().timer)data().timer.task=tid;focus();}break}
case 'duration-picker':openDurationPicker();break;
case 'duration-recent':requestDuration(Number(id));break;
case 'duration-confirm':await applyDuration(Number(id));break;
case 'focus-mode':if(data().timer?.running)return;focusMode=id;data().timer=null;await persist();sheets.pop();focus();$('#timer-number').textContent=timerText();break;
case 'timer-toggle':{let t=data().timer;if(!t){let total=data().preferences[focusMode+'Minutes']*60;t=data().timer=M.entity({mode:focusMode,task:focusTask,total,remaining:total,running:false})}if(t.running){t.remaining=timerRemaining();t.running=false}else{rememberDuration(t.total/60);t.endAt=Date.now()+t.remaining*1000;t.running=true}t.updatedAt=M.now();if(t.running&&window.Native?.requestNotifications)Native.requestNotifications();await persist();sheets.pop();focus();render();break}
case 'timer-stop':data().timer=null;await persist();sheets.pop();focus();render();break;
case 'timer-permission':if(window.Native?.timerSettings)Native.timerSettings();break;
case 'focus-settings':focusSettings();break;
case 'profile':profileEditor();break;
case 'photo-pick':$('#profile-photo-input').click();break;
case 'photo-remove':profilePhoto='';$('#photo-preview').innerHTML=avatar({name:data().preferences.name});break;
case 'clear-due':$('#task-form [name=dueDate]').value='';$('#task-form [name=dueTime]').value='';$('#task-form [name=reminder]').checked=false;$('.schedule-options').open=false;$('.schedule-label').textContent='No date';break;
case 'appearance':sheet('Appearance',`<div class="choices">${['light','dark','system'].map(v=>`<button class="choice ${data().preferences.theme===v?'active':''}" data-action="theme" data-id="${v}">${icon(v==='dark'?'moon':'sun')}${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div>${accentSettings()}<div class="section-head"><h3>Text size</h3></div><div class="segmented">${[[1,'Standard'],[1.12,'Larger'],[1.25,'Largest']].map(([v,l])=>`<button data-action="scale" data-id="${v}" class="${+data().preferences.scale===v?'active':''}">${l}</button>`).join('')}</div><button class="settings-row" data-action="contrast"><span>High contrast</span><span>${data().preferences.contrast?'On':'Off'}</span></button>`);break;
case 'accent':await setThemeAccent(id);break;
case 'theme':data().preferences.theme=['light','dark','system'].includes(id)?id:'system';await persist();sheets.pop();render();action('appearance');break;
case 'scale':data().preferences.scale=+id;await persist();sheets.pop();render();action('appearance');break;
case 'contrast':data().preferences.contrast=!data().preferences.contrast;await persist();sheets.pop();render();action('appearance');break;
case 'notifications':sheet('Notifications',`<p class="help">Reminders are scheduled on your device. Android may delay them when battery saving is active.</p><button class="settings-row" data-action="toggle-notifications"><span>Allow reminders</span><span>${data().preferences.notifications?'On':'Off'}</span></button><button class="text-btn wide" data-action="notification-permission">Open Android notification settings</button><p class="help">Add a date and time to a task, then enable its reminder. Habits have their own reminder time. Timer completion has its own sound and notification channel, scheduled when you start a timer.</p>`);break;
case 'toggle-notifications':data().preferences.notifications=!data().preferences.notifications;if(data().preferences.notifications&&window.Native)Native.requestNotifications();await persist();sheets.pop();action('notifications');render();break;
case 'notification-permission':if(window.Native)Native.notificationSettings();else toast('Available in the Android app.');break;
case 'defaults':sheet('Task defaults',`<form id="defaults-form">${picker('defaultPriority','Default priority',data().preferences.defaultPriority,['none','low','medium','high'].map(p=>[p,p]))}<button class="primary wide">Save defaults</button></form>`);break;
case 'all-tasks':showAllTasks();break;
case 'archive':sheet('Your archive',`<div class="card">${data().boards.filter(b=>b.archived).map(b=>`<button class="settings-row" data-action="restore-board" data-id="${b.id}">${esc(b.name)}<small>Restore board</small></button>`).join('')}${data().tasks.filter(t=>t.archived).map(t=>`<button class="settings-row" data-action="restore-task" data-id="${t.id}">${esc(t.title)}<small>Restore task</small></button>`).join('')}</div><p class="help">Archived items stay on this device and are included in backups.</p>`);break;
case 'restore-board':data().boards.find(b=>b.id===id).archived=false;await persist();closeSheet();action('archive');render();break;
case 'restore-task':data().tasks.find(t=>t.id===id).archived=false;await persist();closeSheet();action('archive');render();break;
case 'export':if(window.Native)Native.exportBackup();else download(`Still_Backup_${M.day()}.json`,'data:application/json;base64,'+btoa(unescape(encodeURIComponent(JSON.stringify(data())))));break;
case 'import':confirmation('Restore from a backup?','A valid backup will replace the data on this device. Export your current data first if you want to keep it.','choose-import');break;
case 'choose-import':if(window.Native)Native.importBackup();else{let i=document.createElement('input');i.type='file';i.accept='.json';i.onchange=async()=>{try{await window.receiveBackup(await i.files[0].text())}catch(e){toast(e.message)}};i.click()}break;
case 'widgets':sheet('A little closer',`<h3>On your home screen</h3><p class="help">Long-press your Android home screen, choose Widgets, then Still. Add Today, Focus, or Habits.</p><h3 class="gap">Shortcuts</h3><p class="help">Long-press the Still app icon for New task or Focus. In the app, swipe a task right to complete it, swipe left for actions, or long-press for a menu.</p>`);break;
case 'app-updates':updateSheet();break;
case 'check-updates':checkAppUpdates();break;
case 'download-update':if(updateResult?.status==='available')Native.openUpdateDownload(updateResult.url);break;
case 'release-page':window.Native?.openUpdateDownload('https://github.com/dannyzeeje/still/releases');break;
case 'about':sheet('Still',`<h1 class="serif">Your day, gently.</h1><p class="help gap">Version 1.18 · Community release<br>Designed for a calmer relationship with your time.</p><div class="card gap"><div class="settings-row">No account. No tracking.</div><div class="settings-row">No ads. Updates checked only when requested.</div><div class="settings-row">Stored locally with SQLite on Android.</div></div><p class="help">Keep a backup before uninstalling or clearing app data. Exported backups contain your private information; save them somewhere you trust.</p>`);break;
}}
document.addEventListener('click',async e=>{if(Date.now()<suppressClickUntil){e.preventDefault();return}let priority=e.target.closest('[data-priority]');if(priority){let field=priority.closest('.priority-field');field.querySelector('input').value=priority.dataset.priority;field.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===priority);b.setAttribute('aria-pressed',b===priority)});return}let p=e.target.closest('[data-picker]');if(p){let box=p.parentElement.querySelector('.inline-choices');box.hidden=!box.hidden;p.setAttribute('aria-expanded',!box.hidden);return}let c=e.target.closest('[data-pick-value]');if(c){let name=c.dataset.pickName,v=c.dataset.pickValue,wrap=c.closest('.inline-picker'),inp=wrap.querySelector('input'),btn=wrap.querySelector('[data-picker]');inp.value=v;btn.textContent=c.textContent;btn.setAttribute('aria-expanded','false');wrap.querySelector('.inline-choices').hidden=true;wrap.querySelectorAll('.choice').forEach(x=>x.classList.toggle('active',x===c));if(name==='repeat'){let f=$('#task-form');f.elements.interval.value=1;syncRepeatOptions()}if(name==='board'&&$('#task-list-picker'))$('#task-list-picker').innerHTML=picker('listId','List','',listOptions(v));if(name==='noteFont'||name==='noteSize'){applyNoteStyle();queueNoteSave();}if(name==='focusTask'){focusTask=v;if(data().timer){data().timer.task=v;await persist()}}return}if(e.target.classList.contains('backdrop')){closeSheet();return}let b=e.target.closest('[data-action]');if(b){e.preventDefault();try{await action(b.dataset.action,b.dataset.id,b)}catch(err){console.error(err);toast('Something went wrong. Please try again.')}}});
document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target,v=new FormData(f),id=f.dataset.id;try{if(f.classList.contains('list-edit-form')){await saveListName(id,String(v.get('name')));return}if(f.id==='list-form'){let b=data().boards.find(b=>b.id===state.board),name=String(v.get('name')).trim();if(!name)return;b.lists.push(M.entity({name}));b.updatedAt=M.now();await persist();render();return}if(f.classList.contains('list-task-form')){await addInlineTask(f);return}switch(f.id){case 'welcome-form':case 'profile-form':{let name=String(v.get('name')).trim();if(!name)return;data().preferences.name=name;if(f.id==='profile-form')data().preferences.photo=profilePhoto;await persist();closeAll();render();break}case 'task-form':await saveTask();break;case 'board-form':{let b=data().boards.find(x=>x.id===id)||M.entity({id,lists:[]});Object.assign(b,{name:String(v.get('name')).trim(),icon:v.get('icon'),color:v.get('color'),updatedAt:M.now()});if(!b.name)return;if(!data().boards.some(x=>x.id===id))data().boards.push(b);await persist();closeAll();render();break}case 'sub-form':{let parent=M.allSub(draft.subtasks).find(x=>x.id===f.dataset.parent),title=String(v.get('title')).trim();if(!title)return;if(f.dataset.edit==='true')parent.title=title;else(parent?parent.children:draft.subtasks).push(M.entity({title,done:false,children:[]}));closeSheet();refreshSubtasks();break}case 'habit-form':{let h=data().habits.find(x=>x.id===id)||M.entity({id,completions:[]});let days=v.getAll('days').map(Number);if($('#habit-remind').checked&&!v.get('reminder')){toast('Choose a reminder time.');return;}if(v.get('frequency')==='weekdays'&&!days.length){toast('Choose at least one day.');return}Object.assign(h,{name:String(v.get('name')).trim(),icon:v.get('icon'),color:v.get('color'),frequency:v.get('frequency'),interval:Math.max(1,Math.min(365,Number(v.get('interval'))||1)),days,target:Math.max(1,Math.min(100,Number(v.get('target'))||1)),reminder:$('#habit-remind').checked?v.get('reminder'):'',startDate:v.get('startDate'),paused:v.has('paused'),updatedAt:M.now()});if(!h.name)return;if(!data().habits.some(x=>x.id===id))data().habits.push(h);await persist();closeAll();habits();render();break}case 'folder-form':{let name=String(v.get('name')).trim();if(!name)return;let folder=noteFolders().find(x=>x.id===id);if(folder){folder.name=name;folder.updatedAt=M.now()}else data().preferences.noteFolders.push(M.entity({id,name}));await persist();closeAll();state.tab='notes';notesFolder=id;render();break;}case 'note-form':{if(await flushNote()){closeAll();state.tab='notes';render()}break}case 'focus-settings-form':for(let k of ['focusMinutes','shortMinutes','longMinutes'])data().preferences[k]=Math.max(1,Math.min(1439,Number(v.get(k))||1));await persist();closeSheet();render();break;case 'defaults-form':data().preferences.defaultPriority=v.get('defaultPriority');await persist();closeAll();render();break}}catch(err){console.error(err);toast('Could not save. Please try again.')}});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){state.searchQ=e.target.value;searchResults()}});
document.addEventListener('change',async e=>{if(e.target.id==='habit-remind'){$('#habit-reminder-time').hidden=!e.target.checked;if(!e.target.checked)$('#habit-form [name=reminder]').value='';}if(e.target.name==='dueDate'&&$('.schedule-label'))$('.schedule-label').textContent=e.target.value?(e.target.value===M.day()?'Today':M.date(e.target.value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})):'No date';if(e.target.id==='file-input'){for(let file of e.target.files){if(file.size>5*1024*1024){toast('Please choose attachments under 5 MB.');continue}if(draft.attachments.reduce((a,x)=>a+x.size,0)+file.size>20*1024*1024){toast('A task can hold up to 20 MB of attachments.');break}let encoded=await new Promise((r,j)=>{let fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(file)});draft.attachments.push(M.entity({name:file.name,mime:file.type,size:file.size,data:encoded}))}$('#attachments').innerHTML=attachmentList(draft.attachments)}});
function download(name,url){let a=document.createElement('a');a.download=name;a.href=url;a.click()}
window.receiveBackup=async raw=>{let previous=structuredClone(data());try{let parsed=typeof raw==='string'?JSON.parse(raw):raw;M.validate(parsed);parsed.timerRevision=previous.timerRevision||0;M.replace(parsed);notesFolder='all';data().timer=null;if(!await persist())throw new Error('Unable to save imported data');closeAll();render();toast('Backup restored')}catch(e){M.replace(previous);toast('Backup not restored: '+e.message)}};
window.nativeToast=s=>toast(s);
window.syncNativeTimer=()=>{if(!M.syncNativeTimer())return;let inFocus=sheets.at(-1)?.title==='Focus';if(inFocus){sheets.pop();focus()}if(!sheets.length||inFocus)render();};
window.nativeAction=a=>{if(!data().preferences.name)return;if(a==='focus')focus();if(a==='new-task')taskEditor(null,{dueDate:M.day()});if(a==='habits')habits()};
window.handleBack=()=>{if(window.StillReorder?.cancel())return true;if($('#duration-overlay')){closeDurationPicker();return true;}if($('#color-overlay')){closeColor();return true}if(sheets.length){closeSheet();return true}if(state.board){state.board=null;render();return true}if(state.tab!=='home'){state.tab='home';render();return true}return false};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(window.StillReorder?.cancel())return;if($('#duration-overlay')){closeDurationPicker();return}closeSheet();return}if(e.key==='Tab'&&sheets.length){let focusable=$$('.sheet button:not([disabled]),.sheet input:not([type=hidden]),.sheet textarea,.sheet a,.sheet [contenteditable=true]').filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
let touch=null,longPress,suppressClickUntil=0;
document.addEventListener('pointerdown',e=>{let row=e.target.closest('[data-task]');if(row?.closest('section[data-list]'))return;if(!row||e.target.closest('.check,.task-edit,.task-expansion'))return;touch={x:e.clientX,y:e.clientY,id:row.dataset.task};longPress=setTimeout(()=>{if(touch){haptic();suppressClickUntil=Date.now()+700;action('task-menu',touch.id);touch=null}},600)});
document.addEventListener('pointermove',e=>{if(touch&&(Math.abs(e.clientX-touch.x)>12||Math.abs(e.clientY-touch.y)>12))clearTimeout(longPress)});
document.addEventListener('pointerup',e=>{clearTimeout(longPress);if(!touch)return;let dx=e.clientX-touch.x,dy=e.clientY-touch.y;if(Math.abs(dx)>85&&Math.abs(dy)<45){let id=touch.id;suppressClickUntil=Date.now()+400;e.preventDefault();action(dx>0?'complete':'task-menu',id)}touch=null});
document.addEventListener('pointercancel',()=>{clearTimeout(longPress);touch=null});
document.addEventListener('dragstart',e=>{let el=e.target.closest('[data-task],[data-board]');if(el?.closest('section[data-list]')){e.preventDefault();return}if(el){clearTimeout(longPress);dragged={id:el.dataset.task||el.dataset.board,type:el.dataset.task?'task':'board'};e.dataTransfer.setData('text/plain',dragged.id)}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-list],[data-task],[data-date],[data-board]'))e.preventDefault()});
document.addEventListener('drop',async e=>{e.preventDefault();if(!dragged)return;let target=e.target.closest('[data-task],[data-date],[data-list],[data-board]');if(!target)return;if(dragged.type==='board'&&target.dataset.board){let arr=data().boards,from=arr.findIndex(x=>x.id===dragged.id),to=arr.findIndex(x=>x.id===target.dataset.board);arr.splice(to,0,arr.splice(from,1)[0])}else if(dragged.type==='task'){let t=data().tasks.find(x=>x.id===dragged.id);let column=target.closest('section[data-list]');if(column){t.listId=column.dataset.list;t.board=state.board}if(target.dataset.date){t.dueDate=target.dataset.date;if(target.dataset.slot)t.dueTime=target.dataset.slot}if(target.dataset.task&&target.dataset.task!==t.id){let arr=data().tasks,from=arr.indexOf(t),to=arr.findIndex(x=>x.id===target.dataset.task);arr.splice(to,0,arr.splice(from,1)[0])}t.updatedAt=M.now()}dragged=null;await persist();render()});
let startupComplete=false;
async function finishStartup(){if(startupComplete)return;startupComplete=true;if(document.fonts?.ready)await Promise.race([document.fonts.ready,new Promise(resolve=>setTimeout(resolve,2500))]);requestAnimationFrame(()=>requestAnimationFrame(()=>{document.body.classList.remove('starting');window.Native?.appReady?.()}))}
async function carryoverDay(){if(!M.rolloverOverdue())return false;if(await persist()){render();return true}return false}
M.open().then(async()=>{await persist();render();setInterval(timerTick,1000);setInterval(()=>carryoverDay(),30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){carryoverDay();window.syncNativeTimer();timerTick();if(!sheets.length&&lastRenderedDay!==M.day())render();updateViewport()}});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);if(window.Native){let a=Native.launchAction();if(a)window.nativeAction(a)}finishStartup()}).catch(e=>{$('#app').innerHTML='<div class="onboarding"><h1>Unable to open your data.</h1><p>Please reopen Still. Your data has not been changed.</p></div>';console.error(e);finishStartup()});

document.addEventListener('input',e=>{if(e.target.matches('#task-form [name=description]'))resizeTaskDetails();if(e.target.matches('#task-form [name=interval]'))syncRepeatOptions()});

let updateResult=null,updateBusy=false;
function updateSheet(){sheet('App updates',`<div id="update-panel"></div>`,drawUpdatePanel)}
function drawUpdatePanel(){let panel=$('#update-panel');if(!panel)return;let result=updateResult||{},status=result.status,message=updateBusy?'Checking for updates…':status==='available'?`Still ${esc(result.version)} is available.`:status==='current'?'You are up to date.':status==='unpublished'?'The release page is not available yet.':status==='error'?'Could not check for updates. Check your connection and try again.':'Check for a newer release.';panel.innerHTML=`<p class="help">Installed version · 1.18</p><h3 role="status" aria-live="polite">${message}</h3>${status==='available'&&!updateBusy?'<button class="primary wide gap" data-action="download-update">Download update</button>':''}<button class="secondary wide gap" data-action="check-updates" ${updateBusy?'disabled':''}>${updateBusy?'Checking…':'Check for updates'}</button><button class="text-btn wide gap" data-action="release-page">GitHub releases</button><p class="help">Only release information is checked. Your tasks stay on this device. Downloads open in your browser; Android asks you to confirm installation.</p>`}
function checkAppUpdates(){if(updateBusy)return;if(!window.Native?.checkUpdates){updateResult={status:'error'};drawUpdatePanel();return}updateBusy=true;drawUpdatePanel();Native.checkUpdates()}
window.receiveUpdateStatus=result=>{updateBusy=false;updateResult=result;drawUpdatePanel()};
